internal enum FingeringAssigner_testGlobals {
    internal static func buildBeat(_ pitches: List<Double>, _ opts: BuildOptions? = nil) -> Beat {
        let track: Track = Track()
        let staff: Staff = Staff()
        staff.transpositionPitch = opts?.transposition ?? 0.0
        if TypeHelper.isTruthy(opts?.tuning) {
            staff.stringTuning.tunings = opts!.tuning!.slice()
        }
        staff.capo = opts?.capo ?? 0.0
        track.addStaff(staff)
        let bar: Bar = Bar()
        staff.addBar(bar)
        let voice: Voice = Voice()
        bar.addVoice(voice)
        let beat: Beat = Beat()
        voice.addBeat(beat)
        let percussionIndices: List<Double> = opts?.percussionIndices ?? List<Double>()
        do {
            var i: Double = 0.0
            while i < pitches.length {
                let midi: Double = pitches[(i).toInt()]
                let note: Note = Note()
                if percussionIndices.indexOf(i) >= 0 {
                    note.percussionArticulation = midi
                } else {
                    note.octave = Math.floor(midi / 12.0)
                    note.tone = midi - note.octave * 12.0
                }
                beat.addNote(note)
                i += 1
            }
        }
        return beat
    }

    nonisolated(unsafe) internal static let GUITAR_6: List<Double> = List<Double>(64.0, 59.0, 55.0, 50.0, 45.0, 40.0)

    nonisolated(unsafe) internal static let BASS_5: List<Double> = List<Double>(43.0, 38.0, 33.0, 28.0, 23.0)

    internal static func capturePitches(_ beat: Beat) -> List<Double> {
        return beat.notes.map({ (n: Note) -> Double in
            return (n.isPercussion ? -1.0 : n.realValue)
        })
    }

    internal static func expectPitchIdentity(_ beat: Beat, _ tuning: List<Double>, _ originalMidi: List<Double>, _ capo: Double = 0.0, _ transposition: Double = 0.0) {
        do {
            var i: Double = 0.0
            while i < beat.notes.length {
                let note: Note = beat.notes[(i).toInt()]
                if note.isPercussion {
                    i += 1
                    continue
                }
                TestGlobals.expect(Number.isNaN(note.string)).toBe(false)
                TestGlobals.expect(Number.isNaN(note.fret)).toBe(false)
                let stringPitch: Double = capo + tuning[(tuning.length - note.string).toInt()]
                TestGlobals.expect(stringPitch + note.fret).toBe(originalMidi[(i).toInt()] + transposition)
                i += 1
            }
        }
    }
}

